
document.addEventListener('DOMContentLoaded', function() {
  var imgMap = {
    '__LOGO__': 'data:image/png;base64,',
    '__NEWS__': 'data:image/jpeg;base64,',
    '__MOCKUP__': 'data:image/png;base64,',
    '__DOCTOR__': 'data:image/png;base64,',
    '__T1__': 'data:image/png;base64,',
    '__T2__': 'data:image/png;base64,',
    '__T3__': 'data:image/png;base64,',
  };
  document.querySelectorAll('img[data-src]').forEach(function(img) {
    var k = img.getAttribute('data-src');
    if(imgMap[k]) img.src = imgMap[k];
  });

  // Scroll reveal
  var observer = new IntersectionObserver(function(entries) {
    entries.forEach(function(e){ if(e.isIntersecting) e.target.classList.add('visible'); });
  }, {threshold:0.12});
  document.querySelectorAll('.reveal,.reveal-left,.reveal-right').forEach(function(el){ observer.observe(el); });

  // Carousel
  (function(){
    var track = document.getElementById('testiTrack');
    var dots = document.querySelectorAll('.carousel-dot');
    var prev = document.getElementById('testiPrev');
    var next = document.getElementById('testiNext');
    if(!track) return;
    var current = 0, total = track.children.length, timer;
    function goTo(idx){
      current = (idx+total)%total;
      track.style.transform = 'translateX(-'+(current*100)+'%)';
      dots.forEach(function(d,i){ d.classList.toggle('active', i===current); });
    }
    function startAuto(){ timer = setInterval(function(){ goTo(current+1); }, 4000); }
    function stopAuto(){ clearInterval(timer); }
    prev.addEventListener('click',function(){ stopAuto(); goTo(current-1); startAuto(); });
    next.addEventListener('click',function(){ stopAuto(); goTo(current+1); startAuto(); });
    dots.forEach(function(d){ d.addEventListener('click',function(){ stopAuto(); goTo(+d.dataset.index); startAuto(); }); });
    var sx=0;
    track.addEventListener('touchstart',function(e){ sx=e.touches[0].clientX; stopAuto(); },{passive:true});
    track.addEventListener('touchend',function(e){ var dx=sx-e.changedTouches[0].clientX; if(Math.abs(dx)>40) goTo(dx>0?current+1:current-1); startAuto(); },{passive:true});
    startAuto();
  })();
});
